// OpenNext generates this handler during the build; keep all event entrypoints
// in this one tenant Worker so HTTP, inbound mail, outbox jobs and sweeps share
// the same runtime bindings and deployment revision.
// @ts-ignore generated by the OpenNext Cloudflare build
import { default as openNextWorker } from './.open-next/worker.js'

type PrivateEmailBucket = {
  put: (key: string, value: ArrayBuffer, options: {
    httpMetadata: { contentType: string }
    customMetadata: Record<string, string>
  }) => Promise<unknown>
}

type TenantEnv = {
  HELLOADA_TENANT_ID: string
  HELLOADA_SITE_AGENT_TOKEN: string
  HELLOADA_NOTIFICATION_RATE_LIMIT: { limit: (input: { key: string }) => Promise<{ success: boolean }> }
  HELLOADA_MESSAGES_QUEUE_NAME: string
  HELLOADA_MESSAGES_DLQ_NAME: string
  PRIVATE_EMAIL: PrivateEmailBucket
}

type WorkerContext = { waitUntil: (promise: Promise<unknown>) => void }
type InboundEmail = {
  from: string
  to: string
  raw: ReadableStream<Uint8Array>
  rawSize: number
  headers: Headers
  setReject: (reason: string) => void
}
type QueueMessage = {
  body: unknown
  attempts: number
  ack: () => void
  retry: (options?: { delaySeconds?: number }) => void
}
type QueueBatch = { queue: string; messages: QueueMessage[] }
type ScheduledEvent = { scheduledTime: number }

const MAX_RAW_EMAIL_BYTES = 20 * 1024 * 1024
const safeIdentifier = (value: unknown) => typeof value === 'string' && /^[a-z0-9-]{1,63}$/.test(value)

const invokeApp = (
  path: string,
  body: unknown,
  env: TenantEnv,
  context: WorkerContext,
) => {
  if (!env.HELLOADA_SITE_AGENT_TOKEN || !safeIdentifier(env.HELLOADA_TENANT_ID)) {
    throw new Error('Tenant service identity is not configured for message processing.')
  }
  const request = new Request(`https://helloada-internal.invalid${path}`, {
    method: 'POST',
    headers: {
      authorization: `Bearer ${env.HELLOADA_SITE_AGENT_TOKEN}`,
      'content-type': 'application/json',
      'x-helloada-tenant': env.HELLOADA_TENANT_ID,
    },
    body: JSON.stringify(body),
  })
  const handler = openNextWorker as unknown as { fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response> }
  return handler.fetch(request, env, context)
}

const header = (headers: Headers, name: string) => (headers.get(name) || '').slice(0, 998)

const readRawEmail = async (stream: ReadableStream<Uint8Array>, size: number) => {
  if (!Number.isFinite(size) || size < 1 || size > MAX_RAW_EMAIL_BYTES) throw new Error('Inbound email exceeds the supported size limit.')
  const reader = stream.getReader()
  const chunks: Uint8Array[] = []
  let length = 0
  try {
    while (true) {
      const next = await reader.read()
      if (next.done) break
      length += next.value.byteLength
      if (length > MAX_RAW_EMAIL_BYTES) throw new Error('Inbound email exceeds the supported size limit.')
      chunks.push(next.value)
    }
  } finally {
    reader.releaseLock()
  }
  if (length !== size) throw new Error('Inbound email size did not match the received envelope.')
  const raw = new Uint8Array(length)
  let offset = 0
  for (const chunk of chunks) { raw.set(chunk, offset); offset += chunk.byteLength }
  return raw.buffer
}

export default {
  fetch: (request: Request, env: TenantEnv, context: WorkerContext) => {
    const handler = openNextWorker as unknown as { fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response> }
    return handler.fetch(request, env, context)
  },

  async email(message: InboundEmail, env: TenantEnv, context: WorkerContext) {
    let raw: ArrayBuffer
    try {
      raw = await readRawEmail(message.raw, message.rawSize)
    } catch (error) {
      message.setReject(error instanceof Error ? error.message : 'Inbound email could not be accepted.')
      return
    }
    const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', raw))
    const hash = [...digest].map((byte) => byte.toString(16).padStart(2, '0')).join('')
    const rawObjectKey = `inbound/${new Date().toISOString().slice(0, 10)}/${hash}.eml`
    const headers = {
      'message-id': header(message.headers, 'message-id'),
      'in-reply-to': header(message.headers, 'in-reply-to'),
      references: header(message.headers, 'references'),
      subject: header(message.headers, 'subject'),
    }
    try {
      await env.PRIVATE_EMAIL.put(rawObjectKey, raw, {
        httpMetadata: { contentType: 'message/rfc822' },
        customMetadata: { from: message.from.slice(0, 254), to: message.to.slice(0, 254), rawSha256: hash, queued: 'false' },
      })
      const accepted = await invokeApp('/api/helloada/internal/messages/accept-inbound', {
        rawObjectKey, from: message.from, to: message.to, headers, rawSha256: hash,
      }, env, context)
      // The raw object is already durable. The scheduled sweep creates/requeues
      // its canonical Payload receipt if this internal handoff is temporarily down.
      if (!accepted.ok) {
        console.error('helloada_inbound_receipt_rejected', { tenant: env.HELLOADA_TENANT_ID, status: accepted.status, rawObjectKey })
        message.setReject('The tenant inbox could not durably accept this message. Please retry later.')
      }
    } catch (error) {
      console.error('helloada_inbound_receipt_deferred', { tenant: env.HELLOADA_TENANT_ID, rawObjectKey, error: error instanceof Error ? error.message : 'unknown' })
      // Leave the private object intact: the internal request may have reached
      // Payload before its response was lost. The deterministic hash key makes
      // a Cloudflare retry safe and the durable receipt remains processable.
      message.setReject('The tenant inbox could not durably accept this message. Please retry later.')
    }
  },

  async queue(batch: QueueBatch, env: TenantEnv, context: WorkerContext) {
    const isDeadLetter = batch.queue === env.HELLOADA_MESSAGES_DLQ_NAME
    if (!isDeadLetter && batch.queue !== env.HELLOADA_MESSAGES_QUEUE_NAME) {
      throw new Error('The message consumer received an unregistered queue.')
    }
    for (const message of batch.messages) {
      const body = message.body as Record<string, unknown> | null
      const operationId = body && typeof body === 'object' ? body.operationId : undefined
      if (!safeIdentifier(operationId)) {
        console.error('helloada_message_queue_invalid', { tenant: env.HELLOADA_TENANT_ID, attempts: message.attempts })
        message.ack()
        continue
      }
      try {
        const action = isDeadLetter ? 'dead-letter' : 'process'
        const response = await invokeApp(`/api/helloada/internal/messages/${action}`, { operationId }, env, context)
        if (response.ok) message.ack()
        else message.retry({ delaySeconds: Math.min(300, 10 * Math.max(1, message.attempts)) })
      } catch (error) {
        console.error('helloada_message_queue_retry', { tenant: env.HELLOADA_TENANT_ID, operationId, attempts: message.attempts, error: error instanceof Error ? error.message : 'unknown' })
        message.retry({ delaySeconds: Math.min(300, 10 * Math.max(1, message.attempts)) })
      }
    }
  },

  scheduled(event: ScheduledEvent, env: TenantEnv, context: WorkerContext) {
    context.waitUntil(invokeApp('/api/helloada/internal/messages/sweep', { scheduledTime: event.scheduledTime }, env, context).then((response) => {
      if (!response.ok) throw new Error(`Message outbox sweep returned HTTP ${response.status}.`)
    }))
  },
}

// The OpenNext adapter may depend on these named handlers for its internal cache.
// @ts-ignore generated by the OpenNext Cloudflare build
export { DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'
